#include<bits/stdc++.h>

using namespace std;
using ll = long long;


class LopMon {
	private:
		string maMon;
		string tenMon;
		int soTin;
	public:
		LopMon(string hoTen = "", string tenMon = "", double soTin = 0.0){
			this->maMon = hoTen;
			this->tenMon = tenMon;
			this->soTin = (int)soTin;
		}
		void nhap() {
			cout << "Nhap ma mon: ";
			getline(cin >> ws, maMon);
			cout << "Nhap ten mon: ";
			getline(cin, tenMon);
			cout << "Nhap so tin chi: ";
			cin >> soTin;
		}

		void xuat() {
			cout << "Ma mon: " << maMon << ", Ten mon: " << tenMon << ", So tin chi: " << soTin << endl;
		}
		int getSoTin() {
			return this->soTin;
		}
};


class quanLyMon {
	private:
		string maKyHoc;
		int soMonHoc;
		LopMon* dsMonHoc; 
	public:
		quanLyMon(string maKyHoc = "", int soMonHoc = 0) {
			this->maKyHoc = maKyHoc;
			this->soMonHoc = soMonHoc;
			this->dsMonHoc = nullptr;
		}
		~quanLyMon() {
			if (dsMonHoc != nullptr) {
				delete[] dsMonHoc;
			}
		}
		void nhap(){
			cout << "Nhap ma ky hoc: ";
			getline(cin >> ws, maKyHoc);
			cout << "Nhap so mon hoc: ";
			cin >> soMonHoc;
			dsMonHoc = new LopMon[soMonHoc];
			for(int i = 0; i < soMonHoc; i++) {
				cout << "\n--- Nhap thong tin mon hoc thu " << i + 1 << " ---\n";
				dsMonHoc[i].nhap(); 
			}
		}

		void monMaxTin() {
			if (soMonHoc <= 0 || dsMonHoc == nullptr) {
				cout << "\nDanh sach mon hoc trong!" << endl;
				return;
			}
			int maxTin = dsMonHoc[0].getSoTin();
			for (int i = 1; i < soMonHoc; i++) {
				if (dsMonHoc[i].getSoTin() > maxTin) {
					maxTin = dsMonHoc[i].getSoTin();
				}
			}
			cout << "\n--- CAC MON HOC CO SO TIN CHI LON NHAT (" << maxTin << " tin chi) ---\n";
			for (int i = 0; i < soMonHoc; i++) {
				if (dsMonHoc[i].getSoTin() == maxTin) {
					dsMonHoc[i].xuat();
				}
			}
		}

		void xuat(){
			cout << "\n=========================================\n";
			cout << "Ma ky hoc: " << maKyHoc << ", So mon hoc: " << soMonHoc << endl;
			cout << "--- DANH SACH CAC MON HOC ---\n";
			for(int i = 0; i < soMonHoc; i++) {
				cout << i + 1 << ". ";
				dsMonHoc[i].xuat();
			}

			this->monMaxTin(); 
		}
};

int main() {
    quanLyMon ql;
    ql.nhap();
    ql.xuat();
    return 0;
}

